function withNormalizedMaterialViewBoxes(icons: Record<string, IconifyIcon>): Record<string, IconifyIcon> {
  return Object.fromEntries(
    Object.entries(icons).map(function normalizeIconEntry([key, icon]) {
      const override = MATERIAL_ICON_VIEW_BOX_OVERRIDES[key];
      return [key, override ? { ...icon, ...override } : icon];
    })
  );
}

export const materialFileIcons: Record<string, IconifyIcon> = withNormalizedMaterialViewBoxes(
  RAW_MATERIAL_FILE_ICONS
);
